#include "surface_audio.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool v,const char*m){if(!v)throw std::runtime_error(m);}
int main(int argc,char**argv){try{SurfaceAudioConfig cfg;cfg.surfaces.materials.resize(2);cfg.surfaces.materials[0].sound_id=5;cfg.surfaces.materials[1].water=true;cfg.sounds[5]={"roll","slide"};cfg.sounds[11]={"wetroll","wetslide"};cfg.sounds[12]={"deeproll","deepslide"};std::array<WheelContact,4>c{};c[0].grounded=true;c[0].load=2000;c[0].speed=20;c[0].material=0;auto a=surface_audio_control(cfg,c);need(a.voices.count(5)&&a.voices[5][0]>0&&a.voices[5][1]==0,"loaded tarmac rolls");c[0].slip=12;a=surface_audio_control(cfg,c);need(a.voices[5][0]==0&&a.voices[5][1]>0,"slip switches to native skid sample");c[0].load=0;need(surface_audio_control(cfg,c).voices.empty(),"unloaded wheel silent");c[0].load=2000;c[0].grounded=false;need(surface_audio_control(cfg,c).voices.empty(),"airborne wheel silent");c[0].grounded=true;c[0].material=1;c[0].slip=0;need(surface_audio_control(cfg,c).voices.count(11),"shallow water sample");c[0].water_depth=.5f;need(surface_audio_control(cfg,c).voices.count(12),"deep water sample");c[0].material=size_t(-1);need(surface_audio_control(cfg,c).voices.empty(),"unknown prop does not invent surface sound");bool bad=false;try{decode_surface_wave(Bytes{1,2,3});}catch(...){bad=true;}need(bad,"malformed WAV rejected");
 if(argc>1){Resources r(argv[1]);Geometry g;g.source="tracks/forest/forest1/geometry/track_geom.w32";for(auto name:{"tarmac","road","sand","grass","snow","water","bank_rock","mould","ice"})g.materials.push_back({name});auto native=load_surface_audio_config(r,load_wheel_effect_config(r,g,"tracks/forest/forest1/a"));need(native.sounds.size()==13&&native.nominal_pitch==20&&native.pitch_scale==.25f,"all original surface sound definitions");need(native.surfaces.materials[0].sound_id==5&&native.surfaces.materials[1].sound_id==4&&native.surfaces.materials[2].sound_id==3&&native.surfaces.materials[3].sound_id==7&&native.surfaces.materials[4].sound_id==8,"native SurfaceSound references resolved");need(native.surfaces.materials[6].sound_id==10&&native.surfaces.materials[7].sound_id==2&&native.surfaces.materials[8].sound_id==13,"rock/wet mud/ice native mapping");need(native.splash_speed==5&&native.splash_delay==3&&native.splash=="sound/impact/tyres_water_crash.wav","native WaterCrash settings");SurfaceAudioMixer mix(r,native);need(mix.diagnostics()["errors"].empty(),"all original WAVs decoded");c={};for(auto&w:c){w.grounded=true;w.load=2000;w.speed=20;w.material=0;}mix.update(c,0,1,true);double energy=0;for(int i=0;i<44100;i++){float v=mix.frame();need(std::isfinite(v),"finite audio output");energy+=v*v;}need(energy>1,"audible native rolling waveform");mix.update(c,.1,1,false);for(int i=0;i<132300;i++)mix.frame();float tail=0;for(int i=0;i<100;i++)tail+=std::abs(mix.frame());need(tail<.001,"pause mutes loops after fade");mix.update(c,.2,1,true);c[0].material=5;mix.update(c,.3,1,true);need(mix.diagnostics()["water_entry_count"]==1,"entering water triggers one shot");mix.update(c,.31,1,true);need(mix.diagnostics()["water_entry_count"]==1,"continuous water contact does not retrigger");c[0].material=0;mix.update(c,.4,1,true);c[0].material=5;mix.update(c,.45,1,true);need(mix.diagnostics()["water_entry_count"]==1,"native splash cooldown");mix.update(c,.46,2,true);need(mix.diagnostics()["water_entry_count"]==1,"recover in water does not fake entry");std::cout<<mix.diagnostics().dump()<<" energy="<<energy<<'\n';}
 std::cout<<"surface audio tests passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
